-- Source checks recorded on 14 October 2026; editorial facts, not visitor sentiment.
INSERT INTO vg_place_research(place_id,topic,title,summary,source_url,publisher,source_kind,source_published_at,checked_at,limitations,status)
SELECT p.id,v.topic,v.title,v.summary,v.source_url,v.publisher,v.source_kind,v.published::date,'2026-10-14T01:08:50.013439+00:00'::timestamptz,
 'Pemeriksaan sumber daring. Kondisi operasional dapat berubah; periksa informasi pengelola menjelang kunjungan.','approved'
FROM (VALUES
('situ-bagendit','pemandangan','Danau dengan latar pegunungan','Indonesia.travel menggambarkan panorama danau dengan latar Gunung Guntur, Putri, Papandayan, dan Cikuray. Ini deskripsi destinasi dari sumber pariwisata.','https://www.indonesia.travel/id/id/travel-ideas/adventure/situ-bagendit','Kementerian Pariwisata — Indonesia.travel','authority',NULL),
('situ-bagendit','fasilitas','Fasilitas rekreasi dan kawasan danau','Panduan mencantumkan masjid apung, amphitheater, kios cinderamata, dan area bermain anak. Ketersediaan fasilitas pada hari kunjungan perlu diperiksa kepada pengelola.','https://www.indonesia.travel/id/id/travel-ideas/adventure/situ-bagendit','Kementerian Pariwisata — Indonesia.travel','authority',NULL),
('situ-bagendit','keluarga','Area bermain dan pilihan aktivitas air','Indonesia.travel mencantumkan area bermain anak, perahu rakit, dan sepeda air. Periksa aturan pendampingan serta layanan yang beroperasi sebelum menggunakan wahana.','https://www.indonesia.travel/id/id/travel-ideas/adventure/situ-bagendit','Kementerian Pariwisata — Indonesia.travel','authority',NULL),
('situ-bagendit','akses','Lokasi di Sukamukti, Banyuresmi','Panduan menempatkan Situ Bagendit di Desa Sukamukti, Kecamatan Banyuresmi. Informasi rute melewati Jalan Jenderal Sudirman dan Jalan H. Hasan Arif dicantumkan sebagai acuan perjalanan.','https://www.indonesia.travel/id/id/travel-ideas/adventure/situ-bagendit','Kementerian Pariwisata — Indonesia.travel','authority',NULL),
('bale-tingtrim-resto','fasilitas','Ruang makan dan fasilitas pendukung','Halaman fasilitas pengelola mencantumkan ruang makan lesehan, musala, toilet, dan ruang pertemuan. Daftar ini merupakan keterangan penyedia.','https://baletingtrimresto.com/fasilitas','Bale Tingtrim Resto','operator',NULL),
('bale-tingtrim-resto','keluarga','Playground dan ruang makan keluarga','Pengelola mencantumkan playground serta pilihan ruang makan keluarga. Konfirmasikan fasilitas dan tempat duduk yang sesuai untuk rombongan sebelum reservasi.','https://baletingtrimresto.com/fasilitas','Bale Tingtrim Resto','operator',NULL),
('bale-tingtrim-resto','parkir','Area parkir pada halaman fasilitas','Pengelola menampilkan parkir depan dan belakang pada halaman fasilitas. Informasi ini tidak memastikan kapasitas kosong pada waktu kedatangan.','https://baletingtrimresto.com/fasilitas','Bale Tingtrim Resto','operator',NULL),
('bale-tingtrim-resto','pelayanan','Jam operasional yang dicantumkan pengelola','Halaman kontak mencantumkan jam 10.00–22.00 untuk Senin sampai Minggu dan kanal reservasi WhatsApp. Konfirmasikan jam layanan menjelang kedatangan.','https://baletingtrimresto.com/kontak','Bale Tingtrim Resto','operator',NULL),
('bale-tingtrim-resto','akses','Alamat pada kanal pengelola','Halaman kontak mencantumkan Jalan Otto Iskandardinata No. 64, Cimanganten, Tarogong Kaler, Kabupaten Garut. Gunakan petunjuk pengelola untuk menentukan titik kedatangan.','https://baletingtrimresto.com/kontak','Bale Tingtrim Resto','operator',NULL),
('curug-sanghyang-taraje','akses','Akses jalan dalam laporan Agustus 2026','Rilis Pemkab pada 2 Agustus 2026 menyebut usulan pembenahan akses sekitar 2,5 km dan penerangan jalan. Ini usulan saat rilis, tanpa konfirmasi penyelesaian perbaikannya.','https://www.garutkab.go.id/berita/curug-sanghyang-taraje-diproyeksikan-jadi-destinasi-unggulan-garut','Pemerintah Kabupaten Garut','authority','2026-08-02'),
('curug-sanghyang-taraje','pemandangan','Konsep kawasan alami','Dalam rilis Pemkab Agustus 2026, pengelola menjelaskan bahwa konsep alami kawasan dipertahankan. Deskripsi ini merupakan konteks pengelolaan tempat.','https://www.garutkab.go.id/berita/curug-sanghyang-taraje-diproyeksikan-jadi-destinasi-unggulan-garut','Pemerintah Kabupaten Garut','authority','2026-08-02')
) AS v(slug,topic,title,summary,source_url,publisher,source_kind,published)
JOIN vg_places p ON p.slug=v.slug AND p.status='published'
ON CONFLICT(place_id,source_url,topic) DO UPDATE SET title=EXCLUDED.title,summary=EXCLUDED.summary,publisher=EXCLUDED.publisher,source_kind=EXCLUDED.source_kind,source_published_at=EXCLUDED.source_published_at,checked_at=EXCLUDED.checked_at,limitations=EXCLUDED.limitations;
